from pathlib import Path
p=Path('projects.js');s=p.read_text(encoding='utf-8-sig');a=s.index('<el-dialog');b=s.index('</el-dialog>',a);s=s[:a]+'''<el-dialog :title="editing?'編輯專案':'新增專案'" :visible.sync="visible" width="640px" custom-class="project-dialog" append-to-body><el-form label-width="140px" @submit.native.prevent="save"><el-form-item label="狀態"><el-switch v-model="draft.enabled" aria-label="專案狀態"></el-switch></el-form-item><el-form-item label="Project ID" required><el-input v-model="draft.code" maxlength="50" placeholder="請輸入 Project ID（系統代號，例如 tickets）"></el-input></el-form-item><el-form-item label="專案英文名稱" required><el-input v-model="draft.englishName" maxlength="100" placeholder="請輸入專案英文名稱（例如 tickets）"></el-input></el-form-item><el-form-item label="專案中文名稱" required><el-input v-model="draft.name" maxlength="50" placeholder="請輸入專案中文名稱（例如 售票網）"></el-input></el-form-item><el-form-item label="專案描述"><el-input v-model="draft.description" type="textarea" :rows="3" placeholder="請輸入專案描述"></el-input></el-form-item><el-form-item label="備註"><el-input v-model="draft.notes" type="textarea" :rows="3" placeholder="請輸入備註資訊"></el-input></el-form-item><p class="records-error" role="alert">{{ error }}</p></el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">確定</el-button></span>'''+s[b:]
s=s.replace("({id,name,code,enabled,updated:'-'})","({id,name,code,englishName:code,description:'',notes:'',enabled,updated:'-'})")
s=s.replace("{name:'',code:'',enabled:true}","{name:'',code:'',englishName:'',description:'',notes:'',enabled:true}")
s=s.replace("code=this.draft.code.trim();if(!name||!code){this.error='請填寫專案名稱與專案代碼'","code=this.draft.code.trim(),englishName=this.draft.englishName.trim();if(!name||!code||!englishName){this.error='請填寫 Project ID、專案英文名稱與專案中文名稱'")
s=s.replace("{...this.draft,name,code}","{...this.draft,name,code,englishName}").replace("{...this.draft,name,code,id:","{...this.draft,name,code,englishName,id:")
p.write_text(s,encoding='utf-8')
